        inicio: '2026-10-19T09:00:00-03:00',
        fim: '2026-10-19T10:00:00-03:00'
      }]
    })
  });
  assert.strictEqual(resTipo.status, 422);
  const bodyTipo = await resTipo.json();
  assert.strictEqual(bodyTipo.erro, 'DADOS_INVALIDOS');
});

