test('POST /atividades/:id/cancelamento ignora corpo de requisição enviado (R20)', async () => {
  const createRes = await fetch(`http://localhost:${port}/atividades`, {
    method: 'POST',
    headers: { 'X-Usuario': 'org-ana', 'Content-Type': 'application/json' },
    body: JSON.stringify({
